"""Original French study companions; matched by concept, never claimed as a transcript."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1];guides=[]
def add(id,title,terms,body,example,output,q,opts,answer,explanation,steps=None):
 guides.append(dict(id=id,title=title,terms=terms,body=body,example=example,output=output,steps=steps or [{'title':'Repérer la règle','text':body.split('. ')[0]+'.'},{'title':'Suivre le calcul ou l’exemple','code':example},{'title':'Vérifier et expliquer','text':output}],questions=[dict(question=q,options=opts,answer=answer,explanation=explanation)],author='Nunya',status='brouillon',scope='Notion associée ; ne remplace pas une transcription du contenu source.'))
def existing(course,n,terms):
 l=json.load(open(root/'content/fr'/f'{course}.json'))['lessons'][n];add(course+'-'+str(n),l['title'],terms,l['body'],l['code'],l['output'],l['question'],l['options'],l['answer'],l['explanation'])
for c,n,terms in [
 ('maths',0,['fraction','numérateur','dénominateur']),('maths',1,['proportionnalité','proportionnel','prix unitaire']),('maths',2,['pourcentage','pour cent']),('maths-seconde',0,['priorité des opérations','ordre des opérations']),('maths-seconde',1,['équation linéaire','équations du premier degré','résoudre une équation']),('maths-seconde',2,['factoriser','factorisation','distributivité','développer une expression']),('maths-seconde',3,['image et antécédent','fonction affine','fonctions linéaires']),('maths-seconde',5,['pythagore','triangle rectangle']),('maths-seconde',6,['médiane','quartile','écart interquartile']),('data',1,['moyenne arithmétique','calculer la moyenne']),('data',2,['diagramme','histogramme','graphique en barres']),('terminale-analyse',0,['domaine de définition','ensemble de définition']),('terminale-analyse',1,['limite','continuité']),('terminale-analyse',2,['dérivée','dérivation','tangente']),('terminale-analyse',3,['tableau de variation','extremum','maximum','minimum']),('terminale-analyse',4,['suite arithmétique']),('terminale-analyse',5,['suite géométrique','croissance exponentielle']),('terminale-mecanique',0,['travail d’une force','travail d\'une force']),('terminale-mecanique',2,['énergie cinétique']),('terminale-mecanique',3,['énergie mécanique','énergie potentielle']),('physics',2,['puissance électrique','kilowattheure','consommation électrique']),('ou-electronique-fr',1,['loi d’ohm','loi d\'ohm','résistance électrique']),('ou-electronique-fr',2,['diviseur de tension']),('javascript',0,['variable','constante','déclaration de variable']),('javascript',1,['condition','instruction if','instructions conditionnelles']),('javascript',2,['fonction javascript','paramètre','valeur de retour']),('javascript',3,['boucle','tableau javascript','liste javascript']),('web',1,['balise html','élément html','structure html']),('web',2,['sélecteur css','feuille de style','mise en forme css']),('web',4,['addEventListener','événement','dom']),('biology',0,['cellule','organite','cytoplasme']),('business',1,['recettes','bénéfice','profit','coût total'])]:existing(c,n,terms)
add('negative','Calculer avec des nombres relatifs',['nombre négatif','nombres relatifs','droite graduée','soustraction des entiers'],'Un nombre négatif se situe à gauche de zéro sur une droite graduée. Ajouter un nombre positif déplace vers la droite ; soustraire un nombre positif déplace vers la gauche. Écris les signes avant de calculer.','−3 + 5 = 2\n2 − 4 = −2','Le résultat final vaut −2.','Combien vaut −4 + 7 ?',['−11','3','11'],1,'Partir de −4 et avancer de 7 unités vers la droite conduit à 3.')
add('powers','Comprendre les puissances',['puissance','exposant','notation scientifique'],'Une puissance aⁿ, pour n entier positif, représente un produit de n facteurs égaux à a. Les parenthèses distinguent une base négative d’un signe placé devant la puissance. Pour a non nul, a⁰ = 1.','2³ = 2 × 2 × 2 = 8\n(−2)² = 4 ; −2² = −4','L’exposant indique le nombre de facteurs, pas une multiplication par cet exposant.','Combien vaut 3³ ?',['9','27','6'],1,'3³ = 3 × 3 × 3 = 27.')
add('quadratic','Résoudre une équation du second degré',['second degré','discriminant','trinôme','équation quadratique'],'Pour ax² + bx + c = 0 avec a non nul, le discriminant vaut Δ = b² − 4ac. Si Δ est positif, les deux solutions réelles sont (−b − √Δ)/(2a) et (−b + √Δ)/(2a). Si Δ = 0, il y a une solution double ; si Δ est négatif, il n’y a pas de solution réelle.','x² − 5x + 6 = 0\nΔ = 25 − 24 = 1\nx = (5 − 1)/2 = 2 ou (5 + 1)/2 = 3','Les solutions sont 2 et 3.','Quelles sont les solutions réelles de x² − 9 = 0 ?',['3 seulement','−3 et 3','−9 et 9'],1,'x² − 9 = (x − 3)(x + 3). Le produit est nul si x vaut 3 ou −3.')
add('trigonometry','Choisir un rapport trigonométrique',['sinus','cosinus','tangente trigonométrique','trigonométrie'],'Dans un triangle rectangle, pour un angle aigu θ, sin θ = opposé/hypoténuse, cos θ = adjacent/hypoténuse et tan θ = opposé/adjacent. Repère les côtés par rapport à l’angle choisi avant d’utiliser une formule.','Opposé = 3 ; adjacent = 4 ; hypoténuse = 5\nsin θ = 3/5 = 0,6\ncos θ = 4/5 = 0,8','Le rapport dépend du côté et de l’angle considérés.','Si opposé = 6 et hypoténuse = 10, sin θ vaut…',['0,6','1,67','4'],0,'sin θ = 6/10 = 0,6.')
add('vectors','Lire les coordonnées d’un vecteur',['vecteur','coordonnées','translation'],'Dans un repère du plan, le vecteur allant de A vers B a pour coordonnées (xB − xA ; yB − yA). Le sens compte : le vecteur de B vers A est son opposé.','A(1 ; 2), B(4 ; 6)\nAB = (4 − 1 ; 6 − 2) = (3 ; 4)','On soustrait les coordonnées du départ à celles de l’arrivée.','Avec A(2 ; 1) et B(5 ; 3), AB vaut…',['(7 ; 4)','(3 ; 2)','(−3 ; −2)'],1,'AB = (5 − 2 ; 3 − 1) = (3 ; 2).')
add('logs','Relier logarithme et exponentielle',['logarithme','logarithmique','fonction exponentielle'],'Le logarithme népérien est défini pour les réels strictement positifs. Il est la fonction réciproque de l’exponentielle : ln(eˣ) = x et e^(ln x) = x pour x positif. Les règles du logarithme exigent de vérifier le domaine.','e⁰ = 1\nln(1) = 0\nln(e²) = 2','Logarithme et exponentielle permettent de revenir à la valeur de départ.','Que vaut ln(e³) ?',['e','3','1'],1,'L’identité ln(eˣ) = x donne ici 3.')
add('integral','Interpréter une intégrale',['intégrale','primitive','intégration'],'Si F est une primitive de f sur un intervalle, l’intégrale de f entre a et b vaut F(b) − F(a). Elle représente une aire algébrique : les parties sous l’axe comptent négativement.','f(x) = 2x ; F(x) = x²\nIntégrale entre 0 et 2 : F(2) − F(0) = 4','L’aire algébrique vaut 4 unités d’aire.','L’intégrale de la fonction constante 3 entre 0 et 2 vaut…',['3','5','6'],2,'C’est l’aire d’un rectangle de largeur 2 et hauteur 3 : 2 × 3 = 6.')
add('probability','Calculer une probabilité simple',['probabilité','probabilités','événement','équiprobable'],'Dans une expérience où les issues sont équiprobables, la probabilité d’un événement est le nombre d’issues favorables divisé par le nombre total d’issues. Elle se situe entre 0 et 1. Cette formule de comptage suppose bien l’équiprobabilité.','Dé équilibré : six issues\nObtenir un nombre pair : 2, 4, 6\nP(pair) = 3/6 = 1/2','Une chance sur deux dans ce modèle.','Avec un dé équilibré, P(obtenir 6) vaut…',['1/6','1/2','6'],0,'Une seule issue favorable sur six issues équiprobables : 1/6.')
add('dna','ADN : conserver et transmettre une information',['adn','gène','génétique','chromosome','réplication','nucléotide'],'L’ADN porte une information sous la forme d’une séquence de nucléotides. Dans une double hélice, A s’apparie avec T et C avec G. Un gène est une région de l’ADN ; un chromosome est une structure contenant de l’ADN associé à des protéines.','Brin : A T C G\nBrin complémentaire : T A G C','La complémentarité repose sur des appariements précis.','Quelle base s’apparie avec C dans l’ADN ?',['A','T','G'],2,'Dans l’ADN à double brin, la cytosine C s’apparie avec la guanine G.')
add('expression','De l’ADN à une protéine',['transcription','traduction','arn','ribosome','protéine'],'Pour un gène codant une protéine, la transcription produit un ARN à partir d’une séquence d’ADN. Lors de la traduction, le ribosome lit l’ARN messager et assemble des acides aminés. Il faut distinguer ces deux étapes et leurs produits.','ADN → transcription → ARN messager\nARN messager → traduction → chaîne d’acides aminés','La transcription produit un ARN ; la traduction assemble une chaîne protéique.','Quel élément réalise la traduction de l’ARN messager ?',['Le ribosome','Un chromosome entier','La membrane plasmique seule'],0,'Le ribosome lit l’ARN messager et participe à l’assemblage de la chaîne d’acides aminés.')
add('division','Distinguer mitose et méiose',['mitose','méiose','division cellulaire','cycle cellulaire'],'La mitose répartit des chromosomes dupliqués entre deux cellules filles et conserve habituellement le nombre de chromosomes. La méiose comporte deux divisions et réduit ce nombre de moitié dans la formation de cellules haploïdes. La duplication de l’ADN précède la division ; elle ne constitue pas une division à elle seule.','Cellule diploïde fictive : 2n = 8\nAprès mitose : chaque cellule fille conserve 8 chromosomes\nAprès méiose : les cellules obtenues ont n = 4','Le résultat dépend du type de division.','Dans ce modèle, une méiose réduit 2n = 12 à…',['12','6','24'],1,'Le nombre de chromosomes est réduit de moitié : n = 6.')
add('selection','Comprendre la sélection naturelle',['évolution','sélection naturelle','adaptation','biodiversité'],'Dans une population, des variations héréditaires peuvent influencer la survie et la reproduction dans un environnement donné. Si certains individus laissent davantage de descendants, la fréquence de ces variantes peut changer au fil des générations. Une population évolue ; un individu ne choisit pas une mutation pour répondre à un besoin.','Variation héréditaire → différences de succès reproducteur\nPlusieurs générations → changement possible des fréquences','Le mécanisme porte sur les générations d’une population.','À quelle échelle décrit-on l’évolution par sélection naturelle ?',['Le choix conscient d’un individu','Les générations d’une population','Une seule journée de croissance'],1,'La sélection naturelle modifie les fréquences de caractères héréditaires dans une population au fil des générations.')
add('photosynthesis','Photosynthèse : transformer l’énergie lumineuse',['photosynthèse','chloroplaste','chlorophylle'],'La photosynthèse convertit une partie de l’énergie lumineuse en énergie chimique. Dans le bilan simplifié usuel, du dioxyde de carbone et de l’eau permettent de former des glucides et du dioxygène. Chez les plantes, cette activité se déroule dans les chloroplastes. Les plantes réalisent aussi la respiration cellulaire.','Lumière + CO₂ + eau → matière organique + O₂\nCette écriture est un bilan simplifié, pas une seule réaction élémentaire.','L’énergie lumineuse est convertie et stockée sous forme chimique.','Quel organite est associé à la photosynthèse chez les plantes ?',['Le chloroplaste','Le ribosome uniquement','Le noyau uniquement'],0,'Les chloroplastes contiennent les structures impliquées dans la photosynthèse.')
add('respiration','Respiration cellulaire : transférer de l’énergie',['respiration cellulaire','glycolyse','mitochondrie','atp','cycle de krebs'],'Les cellules transfèrent l’énergie chimique de molécules vers des formes utilisables, notamment l’ATP. Dans la respiration aérobie, le dioxygène participe au processus et les produits finaux comprennent du dioxyde de carbone et de l’eau. La glycolyse a lieu dans le cytosol ; plusieurs étapes ultérieures se déroulent dans les mitochondries des cellules eucaryotes.','Glucose → étapes de dégradation → transfert d’énergie vers l’ATP\nBilan aérobie simplifié : glucose + O₂ → CO₂ + eau','L’ATP sert de relais dans les transferts d’énergie de la cellule.','Où a lieu la glycolyse ?',['Dans le cytosol','Uniquement dans le noyau','À l’extérieur de toutes les cellules'],0,'La glycolyse se déroule dans le cytosol, avant les étapes mitochondriales de la respiration aérobie eucaryote.')
add('membrane','Comprendre les échanges à travers une membrane',['membrane','diffusion','osmose','transport actif'],'Une membrane sépare deux milieux tout en permettant certains échanges. La diffusion tend à suivre un gradient de concentration sans apport direct d’énergie. Un transport actif peut déplacer une substance contre un gradient grâce à une source d’énergie. L’osmose concerne le déplacement de l’eau à travers une membrane sélectivement perméable.','Gradient : concentration élevée → concentration plus faible\nDiffusion simple : déplacement suivant ce gradient\nTransport actif : déplacement possible contre le gradient','Le sens du gradient et l’apport d’énergie permettent de distinguer les mécanismes.','Quel mécanisme peut déplacer une substance contre son gradient grâce à une source d’énergie ?',['La diffusion simple','Le transport actif','Une mesure de longueur'],1,'Un transport actif utilise une source d’énergie pour permettre un déplacement contre le gradient.')
add('enzymes','Le rôle d’une enzyme',['enzyme','catalyse','activation','cinétique enzymatique'],'Une enzyme est un catalyseur biologique qui facilite une réaction en abaissant la barrière d’activation. Elle n’est pas consommée par le bilan de la réaction. Son activité dépend de conditions comme la température et le pH ; une hausse de température n’améliore pas indéfiniment son activité.','Réaction sans catalyseur : barrière d’activation plus élevée\nAvec enzyme : voie de réaction facilitée\nLe bilan énergétique global de la réaction ne change pas.','Une enzyme facilite une transformation, sans fournir gratuitement l’énergie globale de cette transformation.','Que fait une enzyme dans une réaction ?',['Elle abaisse la barrière d’activation','Elle change tous les produits en éléments chimiques','Elle est toujours consommée totalement'],0,'La catalyse propose une voie de réaction avec une barrière d’activation plus faible.')
add('ecology','Lire une relation dans un écosystème',['écosystème','écologie','chaîne alimentaire','réseau trophique','population'],'Un écosystème associe des êtres vivants et leur milieu. Une chaîne alimentaire simplifie les relations de transfert de matière et d’énergie, tandis qu’un réseau représente plusieurs relations. Une modification d’un groupe peut avoir des effets sur d’autres groupes ; une seule observation ne suffit pas à prouver une cause.','Producteur → consommateur primaire → consommateur secondaire\nExemple simplifié : herbe → insecte herbivore → oiseau','Le schéma décrit une relation de consommation simplifiée.','Dans ce schéma, quel organisme est le producteur ?',['L’oiseau','L’insecte','L’herbe'],2,'L’herbe produit de la matière organique grâce à la photosynthèse ; l’insecte et l’oiseau sont des consommateurs.')
add('body-systems','Relier les fonctions des organes',['circulation','cœur','poumon','respiration humaine','digestion','organe','système nerveux','neurone'],'Les organes coopèrent au sein de systèmes. Par exemple, les échanges respiratoires apportent du dioxygène au sang et éliminent du dioxyde de carbone ; la circulation transporte des substances entre les tissus. Comprendre ces fonctions relève ici de la biologie générale, sans interprétation d’un symptôme ni décision de soin.','Échanges dans les poumons ↔ circulation sanguine ↔ tissus\nChaque système contribue à une fonction d’ensemble.','Une fonction de l’organisme dépend de plusieurs organes en interaction.','Quel système assure principalement le transport du sang entre les organes ?',['Le système circulatoire','Le système digestif seul','Le squelette seul'],0,'Le système circulatoire assure ce transport grâce au cœur et aux vaisseaux.')
add('atoms','Distinguer atome, ion et élément',['atome','proton','neutron','électron','numéro atomique','tableau périodique'],'Le noyau d’un atome contient des protons et des neutrons. Le numéro atomique correspond au nombre de protons et identifie l’élément chimique. Un atome neutre possède autant d’électrons que de protons ; un ion a gagné ou perdu des électrons, sans changer d’élément pour autant.','Atome neutre fictif : 11 protons et 11 électrons\nPerte d’un électron : 11 protons et 10 électrons\nCharge de l’ion : +1','Le nombre de protons identifie l’élément ; les électrons influencent sa charge.','Un atome neutre de 8 protons possède combien d’électrons ?',['4','8','16'],1,'La neutralité exige autant d’électrons que de protons, donc 8.')
add('moles','Relier quantité de matière et masse',['mole','quantité de matière','masse molaire','avogadro'],'La quantité de matière n s’exprime en moles. Lorsque la masse m et la masse molaire M sont connues dans des unités compatibles, n = m/M. La masse molaire en g/mol relie une masse en grammes à une quantité en moles.','m = 18 g ; M = 18 g/mol\nn = 18 / 18 = 1 mol','Le quotient de la masse par la masse molaire donne une quantité de matière.','Avec m = 10 g et M = 20 g/mol, n vaut…',['2 mol','0,5 mol','200 mol'],1,'n = m/M = 10/20 = 0,5 mol.')
add('reactions','Équilibrer une équation chimique',['équation chimique','réaction chimique','stœchiométrie','équilibrer'],'Une équation chimique équilibrée conserve le nombre d’atomes de chaque élément. On ajuste les coefficients devant les espèces, sans modifier leurs formules chimiques. Le coefficient 2 devant H₂O représente deux molécules d’eau, pas une nouvelle formule.','2 H₂ + O₂ → 2 H₂O\nHydrogène : 4 atomes de chaque côté\nOxygène : 2 atomes de chaque côté','Les coefficients permettent de conserver les atomes.','Dans 2 H₂O, combien d’atomes d’hydrogène sont représentés ?',['2','4','6'],1,'Chaque H₂O contient 2 atomes d’hydrogène ; deux molécules en contiennent 4.')
add('ph','Lire un pH avec ses hypothèses',['ph','acide','base','acidité','solution aqueuse'],'Le pH renseigne sur l’acidité d’une solution aqueuse. Dans le cadre usuel à 25 °C, un pH inférieur à 7 est acide, un pH de 7 est neutre et un pH supérieur à 7 est basique. L’échelle est logarithmique : un écart d’une unité correspond à un facteur dix sur la grandeur liée à l’acidité, pas à une simple différence linéaire.','À 25 °C, pH 3 : acide\npH 7 : neutre\npH 10 : basique','Les conditions de température et de solution doivent rester précisées.','À 25 °C, une solution aqueuse de pH 5 est…',['acide','neutre','basique'],0,'À cette température et dans ce cadre, 5 est inférieur à 7 : la solution est acide.')
add('bonding','Comparer deux types de liaison',['liaison chimique','liaison covalente','liaison ionique','molécule'],'Dans une liaison covalente, des atomes partagent des électrons. Une liaison ionique est associée à l’attraction entre ions de charges opposées. Ces descriptions sont des modèles utiles pour comprendre certaines propriétés ; toutes les substances ne sont pas constituées de petites molécules isolées.','Covalente : mise en commun d’électrons\nIonique : attraction entre cations et anions\nNaCl solide : réseau d’ions, pas une petite molécule isolée de sel','Le type de modèle aide à expliquer la structure de la substance.','Dans une liaison covalente, les électrons sont principalement…',['partagés entre les atomes','transformés en protons','tous supprimés'],0,'Le modèle covalent repose sur un partage d’électrons entre les atomes.')
add('newton','Relier force et accélération',['newton','accélération','résultante des forces','force nette'],'Dans un référentiel adapté et pour un système de masse constante, la résultante des forces est liée à l’accélération : ΣF = ma. Une force nette nulle correspond à une accélération nulle, ce qui peut signifier un repos ou un mouvement rectiligne uniforme. Force et vitesse ne sont pas la même grandeur.','m = 2 kg ; a = 3 m/s²\nForce résultante : F = 2 × 3 = 6 N','Le calcul concerne la résultante de toutes les forces sur le système.','Pour m = 4 kg et a = 2 m/s², la résultante vaut…',['2 N','6 N','8 N'],2,'F = ma = 4 × 2 = 8 N.')
add('waves','Relier fréquence et période',['onde','fréquence','période','oscillation','signal sinusoïdal'],'Pour un phénomène périodique, la période T est la durée d’un cycle et la fréquence f le nombre de cycles par seconde. Lorsque T est en secondes, f = 1/T en hertz. Ne confonds pas fréquence et amplitude : une oscillation plus ample n’est pas nécessairement plus rapide.','T = 0,02 s\nf = 1 / 0,02 = 50 Hz','Le phénomène effectue 50 cycles par seconde.','Si T = 0,5 s, la fréquence vaut…',['0,5 Hz','2 Hz','5 Hz'],1,'f = 1/T = 1/0,5 = 2 Hz.')
add('density','Calculer une masse volumique',['masse volumique','densité','volume','flottabilité'],'La masse volumique ρ est le rapport de la masse au volume : ρ = m/V. Les unités doivent être cohérentes. Un même nombre peut changer selon l’unité choisie, et une conversion est nécessaire avant de comparer deux matériaux.','m = 200 g ; V = 100 cm³\nρ = 200/100 = 2 g/cm³','Le matériau de cet exemple a une masse volumique de 2 g/cm³.','Avec m = 300 g et V = 100 cm³, ρ vaut…',['3 g/cm³','30 g/cm³','0,3 g/cm³'],0,'ρ = 300/100 = 3 g/cm³.')
add('scarcity','Reconnaître un coût d’opportunité',['rareté','coût d’opportunité','facteur de production','ressources économiques'],'Une ressource limitée oblige à choisir entre plusieurs usages. Le coût d’opportunité correspond à la meilleure possibilité à laquelle on renonce en faisant un choix. Ce n’est pas nécessairement une dépense d’argent. Il faut préciser les alternatives de la situation.','Une heure disponible : réviser les maths ou préparer une affiche\nChoisir l’affiche fait renoncer à l’heure de révision\nDans cet exemple, le temps est la ressource limitée.','Un choix peut avoir un coût même sans paiement.','Si l’on choisit A et renonce à la meilleure alternative B, le coût d’opportunité correspond à…',['B','toutes les dépenses de la vie','zéro dans tous les cas'],0,'Le coût d’opportunité est la meilleure alternative abandonnée, ici B.')
add('market','Lire offre et demande',['offre','demande','équilibre du marché','prix du marché'],'Dans un modèle simple, la demande représente les quantités souhaitées à différents prix et l’offre les quantités proposées. Le point d’équilibre se trouve où les quantités offertes et demandées coïncident. Une variation du prix sur une courbe se distingue d’un déplacement de toute la courbe.','Prix fictif : 500 FCFA\nQuantité offerte : 20 ; quantité demandée : 20\nCes valeurs décrivent un équilibre du modèle.','Un équilibre concerne simultanément un prix et une quantité.','Dans ce modèle, un équilibre correspond à…',['une quantité offerte égale à la quantité demandée','un prix toujours nul','une disparition de tous les coûts'],0,'Les quantités offertes et demandées sont égales au prix d’équilibre dans ce modèle.')
add('inflation','Distinguer variation nominale et pouvoir d’achat',['inflation','pib','produit intérieur brut','macroéconomie','pouvoir d’achat'],'Une valeur nominale est exprimée aux prix courants. Pour comparer des périodes, une valeur réelle tient compte de l’évolution des prix. Une hausse d’un montant nominal ne signifie donc pas automatiquement une hausse équivalente du pouvoir d’achat. Les indicateurs ont un périmètre et une méthode qu’il faut lire.','Indice de prix fictif : 100 → 110\nHausse relative : (110 − 100)/100 × 100 = 10 %','Dans cet exercice, l’indice a augmenté de 10 %.','Un montant qui augmente de 5 % garantit-il une hausse du pouvoir d’achat de 5 % ?',['Oui, toujours','Non, il faut aussi considérer les prix','Seulement si on change la couleur du graphique'],1,'L’évolution des prix doit être prise en compte pour apprécier le pouvoir d’achat.')
groups={'negative':'maths','powers':'maths','quadratic':'maths','trigonometry':'maths','vectors':'maths','logs':'maths','integral':'maths','probability':'maths','dna':'biology','expression':'biology','division':'biology','selection':'biology','photosynthesis':'biology','respiration':'biology','membrane':'biology','enzymes':'biology','ecology':'biology','body-systems':'biology','atoms':'chemistry','moles':'chemistry','reactions':'chemistry','ph':'chemistry','bonding':'chemistry','newton':'physics','waves':'physics','density':'physics','scarcity':'business','market':'business','inflation':'business'}
for g in guides:
 if g['id'] in groups:g['subjects']=[groups[g['id']]]
 elif g['id'].startswith(('maths','terminale-analyse')):g['subjects']=['maths']
 elif g['id'].startswith(('physics','terminale-mecanique','ou-electronique')):g['subjects']=['physics']
